    F('class-dialogs', 'javascript', 'confirm() คืน true/false ตาม OK/Cancel ส่วน alert() ใช้แสดงข้อความ', 'เป็น System dialogs ของ Browser ไม่ใช่ element ที่เพิ่มลง DOM อาจารย์ยกไว้ใช้ทดลองการตัดสินใจและทบทวน if/else', delegation),
    F('f87', 'javascript', 'ใช้ import/export ต้องโหลด script เป็น module เช่น type="module"', 'ในบท Cookie อาจารย์ให้แยก helper ออกจาก main แล้ว import มาใช้ เหตุผลของ type="module" คือใช้ระบบ module ไม่ใช่เพียงเพราะมีไฟล์ JS หลายไฟล์', cookies),
    F('class-date-epoch', 'javascript', 'new Date(0) เป็นวันเวลาในอดีต จึงใช้ในตัวอย่างลบ Cookie ได้', 'CookieUtil.unset ตั้งค่าให้หมดอายุที่จุดเริ่มต้น epoch ปี 1970 ขณะที่ตั้งวันหมดอายุในอนาคตต้องคำนวณเพิ่มจากเวลาปัจจุบันตามหน่วยของโจทย์', cookies),
    F('class-counter', 'javascript', 'visit counter ต้องอ่านค่า → ถ้า null เริ่ม 1 → ไม่เช่นนั้นเพิ่ม → บันทึกและแสดงผล', 'อาจารย์ใช้โจทย์นี้เทียบ local/session และให้สังเกต ++value กับ value++ ว่าเพิ่มก่อนหรือส่งค่าเก่าก่อน ใช้ Number(value) + 1 ทำให้ขั้นตอนชัดได้', webStorage)
